-- Apply to a NEW separate project, then company.sql. No shared business data.
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
create table public.settings(id boolean primary key default true check(id), company text not null check(company in('Delsea','Ambersea')), require_approval boolean not null default true);
create table public.memberships(email text primary key check(email=lower(email)),role text not null check(role in('admin','sales','procurement','management')),active boolean not null default true);
create table public.profiles(id uuid primary key references auth.users on delete cascade, email text not null, display_name text, role text not null check(role in('admin','sales','procurement','management')),active boolean not null default true);
create function private.role() returns text language sql stable security definer set search_path='' as $$
 select p.role from public.profiles p
 join auth.users u on u.id=p.id
 join public.memberships m on m.email=lower(u.email) and m.active and m.role=p.role
 where p.id=(select auth.uid()) and p.active and u.email_confirmed_at is not null
$$;
create function private.member() returns boolean language sql stable set search_path='' as $$select private.role() is not null$$;
create function private.claim() returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null then raise exception 'Sign in required'; end if;
 insert into public.profiles(id,email,display_name,role)
 select u.id,lower(u.email),split_part(u.email,'@',1),m.role from auth.users u
 join public.memberships m on m.email=lower(u.email) and m.active
 where u.id=auth.uid() and u.email_confirmed_at is not null
 on conflict(id) do update set email=excluded.email,role=excluded.role;
end$$;
create function public.claim_membership() returns void language sql set search_path='' as $$select private.claim()$$;
create table public.products(id uuid primary key default gen_random_uuid(),name text not null unique, species text,catch_method text,notes text,created_at timestamptz not null default now());
create table public.buyers(id uuid primary key default gen_random_uuid(),external_id text unique,name text not null check(length(trim(name))>0),country text not null,city text,website text,business_type text,email text,phone text,whatsapp text,wechat text,linkedin text,product_interests text,stage text not null default 'New' check(stage in('New','Contacted','Replied','Qualified','Quotation','Negotiation','Sample','Order','Repeat Buyer','Not Interested','On Hold','Lost','Do Not Contact')),priority text default 'Normal',score numeric check(score between 0 and 100),verification_status text not null default 'Unverified' check(verification_status in('Unverified','Source recorded','Verified')),source_url text,verified_on date,verification_notes text,research_notes text,next_action text,routing_notes text,outreach_gate text,opt_out boolean not null default false,owner_id uuid references profiles,source_data jsonb default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(verification_status<>'Verified' or (source_url is not null and verified_on is not null and verification_notes is not null)));
create unique index buyer_identity on public.buyers(lower(trim(name)),lower(trim(country)));
create table public.contacts(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references buyers,name text,role text,email text,phone text,whatsapp text,wechat text,linkedin text,source_url text,notes text,created_at timestamptz not null default now());
create table public.research_sources(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references buyers,title text,url text,checked_on date,notes text,created_at timestamptz not null default now());
create table public.communications(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references buyers,channel text not null default 'Email',direction text not null default 'Draft' check(direction in('Draft','Outbound','Inbound','Internal')),subject text,body text not null,language text default 'English',evidence text,happened_at timestamptz not null default now(),created_at timestamptz not null default now(),check(direction<>'Outbound' or nullif(trim(evidence),'') is not null));
create table public.tasks(id uuid primary key default gen_random_uuid(),buyer_id uuid references buyers,title text not null,due_on date not null,priority text not null default 'Normal',status text not null default 'Open' check(status in('Open','Completed')),owner_id uuid references profiles,recurring_days int not null default 0 check(recurring_days>=0),notes text,completed_at timestamptz,created_at timestamptz not null default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,location text,products text,contact_name text,email text,phone text,whatsapp text,wechat text,website text,certifications text,verification_source text,verified_on date,capacity_kg numeric,moq_kg numeric,payment_terms text,reliability_notes text,created_at timestamptz not null default now());
create table public.rfqs(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references buyers,title text not null,status text default 'Open',currency text not null default 'USD' check(currency ~ '^[A-Z]{3}$'),incoterm text not null default 'FOB' check(incoterm in('EXW','FOB','CFR','CIF')),destination text,shipment_mode text not null default 'Unspecified' check(shipment_mode in('Mixed container','Separate containers','Unspecified')),containers numeric check(containers>0),payment_terms text,certifications text,delivery_window text,instructions text,owner_id uuid references profiles,created_at timestamptz not null default now());
create table public.rfq_items(id uuid primary key default gen_random_uuid(),rfq_id uuid not null references rfqs,product_id uuid not null references products,species text,form text,grade text,catch_method text,glaze_percent numeric check(glaze_percent between 0 and 100),weight_basis text,packing text,treatment text,quality text,quantity_kg numeric not null check(quantity_kg>0),target_price numeric check(target_price>=0),container_group text,created_at timestamptz not null default now());
create table public.supplier_offers(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references suppliers,rfq_id uuid references rfqs,product_id uuid not null references products,species text,form text,grade text,packing text,certifications text,quantity_kg numeric not null check(quantity_kg>0),unit_price numeric not null check(unit_price>=0),currency text not null default 'USD' check(currency ~ '^[A-Z]{3}$'),incoterm text default 'FOB',additional_cost numeric check(additional_cost>=0),lead_days int,availability_status text default 'Unverified',verified_on date,valid_until date,payment_terms text,notes text,created_at timestamptz not null default now());
create sequence public.quote_number;
create table public.quotes(id uuid primary key default gen_random_uuid(),number text not null unique,revision int not null default 1,previous_quote_id uuid unique references quotes,buyer_id uuid not null references buyers,rfq_id uuid references rfqs,buyer_snapshot jsonb not null,currency text not null check(currency ~ '^[A-Z]{3}$'),incoterm text not null check(incoterm in('EXW','FOB','CFR','CIF')),destination text not null,payment_terms text,shipment_window text,valid_until date not null,notes text,status text not null default 'Draft' check(status in('Draft','Approved','Sent','Accepted','Rejected')),total numeric not null check(total>=0),estimated_cost numeric check(estimated_cost>=0),probability numeric not null default 0 check(probability between 0 and 100),expected_close date,approved_by uuid references profiles,sent_evidence text,acceptance_reference text,created_at timestamptz not null default now());
create table public.quote_items(id uuid primary key default gen_random_uuid(),quote_id uuid not null references quotes,product_id uuid not null references products,description text not null,quantity_kg numeric not null check(quantity_kg>0),unit_price numeric not null check(unit_price>=0),packing text,container_group text,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references buyers,quote_id uuid unique references quotes,po_reference text not null check(length(trim(po_reference))>0),acceptance_reference text not null check(length(trim(acceptance_reference))>0),status text not null default 'Confirmed',currency text not null default 'USD' check(currency ~ '^[A-Z]{3}$'),total numeric not null default 0 check(total>=0),actual_cost numeric check(actual_cost>=0),payment_terms text,expected_delivery date,commercial_model text not null default 'Principal' check(commercial_model in('Principal','Agency')),commission_method text check(commission_method in('Per kg','Percentage','Fixed')),commission_rate numeric check(commission_rate>=0),commission_quantity_kg numeric check(commission_quantity_kg>=0),commission_payer text,commission_agreement text,created_at timestamptz not null default now(),check(commercial_model<>'Agency' or (commission_method is not null and commission_rate is not null and commission_payer is not null and commission_agreement is not null)));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,product_id uuid not null references products,description text,quantity_kg numeric not null check(quantity_kg>0),unit_price numeric not null check(unit_price>=0),packing text,created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,amount numeric not null check(amount>0),currency text not null check(currency ~ '^[A-Z]{3}$'),received_on date not null,reference text not null,notes text,created_at timestamptz not null default now());
create table public.shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,container_number text,bl_reference text,vessel text,port_origin text,port_destination text,etd date,eta date,status text default 'Planned',notes text,created_at timestamptz not null default now());
create table public.inventory(id uuid primary key default gen_random_uuid(),product_id uuid not null references products,lot_number text not null unique,species text,grade text,form text,quality_grade text,glaze_percent numeric check(glaze_percent between 0 and 100),weight_basis text,packing text,iwp text,zig_zag boolean default false,carton_net_kg numeric not null check(carton_net_kg>0),on_hand_kg numeric not null default 0 check(on_hand_kg>=0),location text,production_date date,quality_status text not null default 'Hold' check(quality_status in('Hold','Released','Rejected')),notes text,created_at timestamptz not null default now());
create table public.stock_movements(id uuid primary key default gen_random_uuid(),inventory_id uuid not null references inventory,quantity_kg numeric not null check(quantity_kg<>0),reason text not null,order_id uuid references orders,actor uuid references profiles,created_at timestamptz not null default now());
create table public.reservations(id uuid primary key default gen_random_uuid(),inventory_id uuid not null references inventory,order_id uuid not null references orders,quantity_kg numeric not null check(quantity_kg>0),status text not null default 'Active' check(status in('Active','Released','Dispatched')),created_at timestamptz not null default now());
create table public.temperature_logs(id uuid primary key default gen_random_uuid(),inventory_id uuid not null references inventory,temperature_c numeric not null,measured_at timestamptz not null,location text,notes text,created_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(),buyer_id uuid references buyers,order_id uuid references orders,inventory_id uuid references inventory,name text not null,object_path text not null unique,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 10485760),uploaded_by uuid not null default auth.uid() references profiles,created_at timestamptz not null default now());
create table public.costings(id uuid primary key default gen_random_uuid(),name text not null,rfq_id uuid references rfqs,inputs jsonb not null,results jsonb not null,created_at timestamptz not null default now());
create table public.import_batches(id uuid primary key default gen_random_uuid(),name text not null,results jsonb not null,created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,table_name text not null,record_id text,action text,actor uuid,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
create function private.audit() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into public.audit_log(table_name,record_id,action,actor,old_data,new_data) values(tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'),tg_op,auth.uid(),case when tg_op<>'INSERT' then to_jsonb(old) end,case when tg_op<>'DELETE' then to_jsonb(new) end); return coalesce(new,old); end$$;
create function private.guard() returns trigger language plpgsql set search_path='' as $$begin
 if tg_table_name='buyers' then new.updated_at=now(); end if;
 if tg_table_name='products' then if (select company from public.settings)='Delsea' and (new.name not in('Whole-cleaned octopus','Hook-caught ribbonfish','Net-caught ribbonfish') or (new.name='Hook-caught ribbonfish' and new.catch_method is distinct from 'Hook') or(new.name='Net-caught ribbonfish' and new.catch_method is distinct from 'Net')) then raise exception 'Delsea product scope is restricted'; end if; end if;
 if tg_table_name='communications' then if new.direction='Outbound' and exists(select 1 from public.buyers where id=new.buyer_id and(opt_out or stage='Do Not Contact')) then raise exception 'Buyer is suppressed'; end if; end if;
 if tg_table_name='payments' then if new.currency is distinct from (select currency from public.orders where id=new.order_id) then raise exception 'Payment currency must match order'; end if; end if;
 return new;end$$;
create function private.require_roles(allowed text[]) returns void language plpgsql set search_path='' as $$begin if private.role() is null or not(private.role()=any(allowed)) then raise exception 'Not authorized'; end if;end$$;
DO $$declare t text; roles text;begin
 for t in select tablename from pg_tables where schemaname='public' loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon, authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy member_read on public.%I for select to authenticated using ((select private.member()))',t);
 if t not in('audit_log','quotes','quote_items','stock_movements','reservations') then
 roles=case when t in('settings','profiles','memberships','import_batches') then '''admin''' when t in('products','inventory','temperature_logs','suppliers','supplier_offers') then '''admin'',''procurement''' when t in('documents','tasks','costings') then '''admin'',''sales'',''procurement''' else '''admin'',''sales''' end;
 execute format('grant insert,update,delete on public.%I to authenticated',t);
 execute format('create policy role_insert on public.%I for insert to authenticated with check ((select private.role()) in (%s))',t,roles);
 execute format('create policy role_update on public.%I for update to authenticated using ((select private.role()) in (%s)) with check ((select private.role()) in (%s))',t,roles,roles);
 execute format('create policy admin_delete on public.%I for delete to authenticated using ((select private.role())=''admin'')',t);
 end if;
 if t<>'audit_log' then execute format('create trigger audit after insert or update or delete on public.%I for each row execute function private.audit()',t);end if;
 end loop;
 for t in select unnest(array['products','buyers','communications','payments']) loop execute format('create trigger validate before insert or update on public.%I for each row execute function private.guard()',t);end loop;
end$$;
-- Only approved columns may change, including when a table-level GRANT previously existed.
revoke all on public.settings from authenticated;grant select on public.settings to authenticated;grant update(require_approval) on public.settings to authenticated;
revoke update on public.inventory from authenticated;
grant update(product_id,lot_number,species,grade,form,quality_grade,glaze_percent,weight_basis,packing,iwp,zig_zag,carton_net_kg,location,production_date,quality_status,notes) on public.inventory to authenticated;
revoke insert on public.inventory from authenticated;
grant insert(product_id,lot_number,species,grade,form,quality_grade,glaze_percent,weight_basis,packing,iwp,zig_zag,carton_net_kg,location,production_date,quality_status,notes) on public.inventory to authenticated;
-- FK indexes for relationship queries and deletes.
DO $$declare r record;begin for r in select t.relname,a.attname from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum=c.conkey[1] where c.contype='f' and n.nspname='public' loop execute format('create index if not exists %I on public.%I(%I)',r.relname||'_'||r.attname||'_idx',r.relname,r.attname);end loop;end$$;
create index tasks_due_idx on tasks(due_on) where status='Open';
create index buyer_stage_idx on buyers(stage);
create index audit_record_idx on audit_log(table_name,record_id,created_at desc);
revoke all on all functions in schema private from public,anon;
grant execute on function private.role(),private.member(),private.claim() to authenticated;
revoke all on function public.claim_membership() from public,anon;grant execute on function public.claim_membership() to authenticated;
